    style='''body{font:16px/1.55 system-ui,sans-serif;max-width:1120px;margin:40px auto;padding:0 24px;color:#172e3b;background:#fbfcfd}h1{font-size:32px;line-height:1.2}h2{margin-top:36px;font-size:22px}p{max-width:1000px}.note{padding:14px 18px;border-left:4px solid #b66e3c;background:#fff5ea}.good{border-left:4px solid #237a9b;background:#edf6fa;padding:14px 18px}table{border-collapse:collapse;width:100%;font-size:14px;margin:18px 0}th,td{text-align:left;border-bottom:1px solid #ccd8df;padding:9px}th{background:#eaf1f4}img{width:100%;height:auto;margin-top:12px}a{color:#0d678a}.small{font-size:13px;color:#425e6e}code{font-size:13px}summary{cursor:pointer;font-weight:600}ul{padding-left:24px}@media print{body{margin:0;max-width:none}h2{break-after:avoid}img,table{break-inside:avoid}}'''
    def htmltable(df):return '<div style="overflow-x:auto">'+df.to_html(index=False,border=0,float_format=lambda x:f'{x:.4f}',escape=True)+'</div>'
    display_table=table.replace({'yoy_log':'YoY log','qoq_saar':'q/q SAAR','full27':'Full sample','exclude_three_pandemic':'Exclude 3 pandemic quarters'}).rename(columns={
        'frequency':'Inflation','sample':'Sample','n':'N','headline_slope':'Headline slope','core_slope':'Core slope','core_minus_headline_slope':'Core − headline','nominal_HC3_difference_low':'HC3 low','nominal_HC3_difference_high':'HC3 high'})
